69	/**
70	 * The value of a percentage of an amount. Modifiers are summed as separate
71	 * amounts rather than compounded, so each is computed against its own base:
72	 * a cursed sword is 100 + 50 % of 100 + 10 % of 100, not 100 × 1.5 × 1.1.
73	 *
74	 * Multiplies before dividing, keeping the percentage an integer ratio rather
75	 * than a decimal factor: 100 * 1.1 === 110.00000000000001 in binary floating
76	 * point, which would round the wrong way. Intermediates stay exact and only
77	 * the final premium is rounded.
78	 */
79	const percentOf = (amount: number, percent: number): number =>
80	  (amount * percent) / HUNDRED;
