110	 * Base premium for a group of alike items. A block rate applies only when a
111	 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
112	 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
113	 */
114	const basePremiumOfGroup = (type: string, count: number): number => {
115	  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
116	    return COMPONENT_BLOCK_PREMIUM;
117	  }
118	  return count * basePremiumOfType(type);
119	};
